    "title": "Insights | TrustLed AI",
    "description": "Articles, talks and events on AI governance from TrustLed AI.",
    "bodyHtml": "<section class=\"page-hero\">\n<div class=\"container reveal\">\n<div class=\"breadcrumb\"><a href=\"/\">Home</a> / Insights</div>\n\n<h1 class=\"h1\">Insights</h1>\n<p class=\"lead\">Articles, talks and events on AI governance, regulation and responsible adoption.</p>\n</div>\n</section>\n\n<section class=\"section section--tight\" style=\"padding-bottom:0\">\n<div class=\"container\">\n<h2 class=\"eyebrow mb-16\">Featured</h2>\n<a class=\"featured reveal\" href=\"/unidel-symposium\">\n<div class=\"ph\">[Photo: Franklin Okeke at the UNIDEL symposium]</div>\n<div class=\"featured-body\">\n<span class=\"small muted\">Talk · UNIDEL International Symposium</span>\n<h3 class=\"h2\">From AI Policy to Practice: Building AI Governance that Works in Universities</h3>\n<p>Four ideas for turning an AI policy into the way staff and students work every day.</p>\n<span class=\"link-arrow\">Read more <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg></span>\n</div>\n</a>\n</div>\n</section>\n\n<section class=\"section\">\n<div class=\"container\">\n<div class=\"section-head section-head--row reveal\">\n<h2 class=\"h2\">Latest</h2>\n<div class=\"filters\" role=\"group\" aria-label=\"Filter insights\">\n<button type=\"button\" data-filter=\"all\" aria-pressed=\"true\">All</button>\n<button type=\"button\" data-filter=\"article\" aria-pressed=\"false\">Articles</button>\n<button type=\"button\" data-filter=\"talk\" aria-pressed=\"false\">Talks</button>\n<button type=\"button\" data-filter=\"event\" aria-pressed=\"false\">Events</button>\n</div>\n</div>\n<div class=\"grid grid-3 reveal-stagger\">\n<a class=\"post\" data-type=\"talk\" href=\"/unidel-symposium\">\n<div class=\"ph\">[Photo: UNIDEL symposium]</div>\n<div class=\"small muted\">Talk · UNIDEL International Symposium</div>\n<h3 class=\"h3\">From AI Policy to Practice</h3>\n</a>\n<article class=\"post\" data-type=\"article\">\n<div class=\"ph\">[Article image]</div>\n<div class=\"small muted\">Article · [Date]</div>\n<h3 class=\"h3\">[Article title]</h3>\n</article>\n<article class=\"post\" data-type=\"article\">\n<div class=\"ph\">[Article image]</div>\n<div class=\"small muted\">Article · [Date]</div>\n<h3 class=\"h3\">[Article title]</h3>\n</article>\n<article class=\"post\" data-type=\"event\">\n<div class=\"ph\">[Event image]</div>\n<div class=\"small muted\">Event · [Date]</div>\n<h3 class=\"h3\">[Event title]</h3>\n</article>\n</div>\n</div>\n</section>\n\n<section class=\"section section--soft\">\n<div class=\"container split\">\n<div class=\"reveal\"><h2 class=\"h2 mb-8\">Get new insights by email</h2><p>Practical updates on AI governance and regulation, sent when there is something worth reading.</p></div>\n<form class=\"reveal\" data-form action=\"https://formsubmit.co/hello@trustledai.com\" method=\"POST\">\n<input type=\"hidden\" name=\"_subject\" value=\"Insights subscription from trustledai.com\">\n<input type=\"hidden\" name=\"_template\" value=\"table\">\n<input type=\"hidden\" name=\"_captcha\" value=\"false\">\n<input type=\"hidden\" name=\"_next\" value=\"\">\n<input type=\"hidden\" name=\"Page\" value=\"\">\n<input type=\"text\" name=\"_honey\" class=\"hp\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\">\n<label class=\"sr-only\" for=\"ins-email\">Email address</label>\n<div class=\"inline-form\"><input id=\"ins-email\" type=\"email\" name=\"Email\" placeholder=\"Your email\" required autocomplete=\"email\"><button type=\"submit\" class=\"btn btn-primary\">Subscribe</button></div>\n</form>\n</div>\n</section>",
